46	impl<F: PrimeField> From<i128> for FieldElement<F> {
47	    fn from(mut a: i128) -> FieldElement<F> {
48	        let mut negative = false;
49	        if a < 0 {
50	            a = -a;
51	            negative = true;
52	        }
53	
54	        let mut result = match F::from_str(&a.to_string()) {
55	            Ok(result) => result,
56	            Err(_) => panic!("Cannot convert i128 as a string to a field element"),
57	        };
58	
59	        if negative {
60	            result = -result;
61	        }
62	        FieldElement(result)
63	    }
64	}
