11	/// Performs multi scalar multiplication of points with scalars.
12	pub fn multi_scalar_mul(
13	    points: &[FieldElement],
14	    scalars_lo: &[FieldElement],
15	    scalars_hi: &[FieldElement],
16	) -> Result<(FieldElement, FieldElement, FieldElement), BlackBoxResolutionError> {
17	    if points.len() != 3 * scalars_lo.len() || scalars_lo.len() != scalars_hi.len() {
18	        return Err(BlackBoxResolutionError::Failed(
19	            BlackBoxFunc::MultiScalarMul,
20	            "Points and scalars must have the same length".to_string(),
21	        ));
22	    }
23	
24	    let mut output_point = grumpkin::SWAffine::zero();
25	
26	    for i in (0..points.len()).step_by(3) {
27	        let point =
28	            create_point(points[i], points[i + 1], points[i + 2] == FieldElement::from(1_u128))
29	                .map_err(|e| BlackBoxResolutionError::Failed(BlackBoxFunc::MultiScalarMul, e))?;
30	
31	        let scalar_low: u128 = scalars_lo[i / 3].try_into_u128().ok_or_else(|| {
32	            BlackBoxResolutionError::Failed(
33	                BlackBoxFunc::MultiScalarMul,
34	                format!("Limb {} is not less than 2^128", scalars_lo[i].to_hex()),
35	            )
36	        })?;
37	
38	        let scalar_high: u128 = scalars_hi[i / 3].try_into_u128().ok_or_else(|| {
39	            BlackBoxResolutionError::Failed(
40	                BlackBoxFunc::MultiScalarMul,
41	                format!("Limb {} is not less than 2^128", scalars_hi[i].to_hex()),
42	            )
43	        })?;
44	
45	        let mut bytes = scalar_high.to_be_bytes().to_vec();
46	        bytes.extend_from_slice(&scalar_low.to_be_bytes());
47	
48	        let grumpkin_integer = BigUint::from_bytes_be(&bytes);
49	
50	        // Check if this is smaller than the grumpkin modulus
51	        // if grumpkin_integer >= grumpkin::FrConfig::MODULUS.into() {
52	        //     return Err(BlackBoxResolutionError::Failed(
53	        //         BlackBoxFunc::MultiScalarMul,
54	        //         format!("{} is not a valid grumpkin scalar", grumpkin_integer.to_str_radix(16)),
55	        //     ));
56	        // }
57	
58	        let iteration_output_point =
59	            grumpkin::SWAffine::from(point.mul_bigint(grumpkin_integer.to_u64_digits()));
60	
61	        output_point = grumpkin::SWAffine::from(output_point + iteration_output_point);
62	    }
63	
64	    if let Some((out_x, out_y)) = output_point.xy() {
65	        Ok((
66	            FieldElement::from_repr(*out_x),
67	            FieldElement::from_repr(*out_y),
68	            FieldElement::from(output_point.is_zero() as u128),
69	        ))
70	    } else {
71	        Ok((FieldElement::from(0_u128), FieldElement::from(0_u128), FieldElement::from(1_u128)))
72	    }
